mapper.select:
select nvl(prddeal.PRDQTY,0) "prdqty", nvl(prdrate.PROD_VALUE,1) "prdvalue", prdinfo.RAISE_CCY "raiseccy" from ( select nvl(prddealsub.PRD_QTY,prdraisetotalsub.RAISE_QTY) PRDQTY, nvl(prddealsub.prod_id,prdraisetotalsub.prod_id) prod_id, rank() over (partition by nvl(prddealsub.prod_id,prdraisetotalsub.prod_id) order by prddealsub.mdate desc) rowindex from chb_prd_deal_sub prddealsub full join CHB_PRD_RAISETOT_SUB prdraisetotalsub on prddealsub.prod_id = prdraisetotalsub.prod_id where 1 =1 and to_char(prddealsub.mdate,'yyyy-MM-dd') <= to_char(#{queryDate,jdbcType=DATE},'yyyy-MM-dd') and nvl(prddealsub.SUBMIT_FEEDBACK_STATUS,prdraisetotalsub.SUBMIT_FEEDBACK_STATUS) = '03'/*反馈状态=中债通过*/
) prddeal left join ( select prdrate.prod_id prod_id, prdrate.PROD_VALUE prod_value, rank() over (partition by prdrate.prod_id order by prdrate.CHANGE_DATE desc) ranknum from chb_prd_periodyield prdrate where 1 =1
and prdrate.CHANG_TYPE = '01' /*变动类型=净值变动*/ and to_char(prdrate.CHANGE_DATE,'yyyy-MM-dd') <= to_char(#{queryDate,jdbcType=DATE},'yyyy-MM-dd') )prdrate on prddeal.prod_id = prdrate.prod_id and prdrate.ranknum = 1 left join chb_prd_baseinfo prdinfo on prdinfo.prod_id = prddeal.prod_id where 1 =1 and prdinfo.status in ('E','M')/*有效状态：有效、修改*/ and prddeal.rowindex = 1 and nvl(prdinfo.fprod_id,'NULLFP') = 'NULLFP'/*过滤母产品*/
